import {
	type BootDevServerMutationHookResult,
	type BootDevServerMutationVariables,
	useBootDevServerMutation
} from '@/generated/graphql'
import { useThrottledCallback } from 'use-debounce'
import { create } from 'zustand'

type Vars = BootDevServerMutationVariables

type Cache = {
	result: ReturnType<BootDevServerMutationHookResult[0]>
	timestamp: number
}
export const useArgMapStore = create<{
	argMap: Map<string, Cache>
	reset: () => void
}>((set) => ({
	argMap: new Map<string, Cache>(),
	reset: () => {
		set({ argMap: new Map<string, Cache>() })
	}
}))
export const useThrottledBootDevServer = () => {
	const [bootDevServer] = useBootDevServerMutation()
	const argMap = useArgMapStore((state) => state.argMap)
	const throttled = useThrottledCallback(
		(args: Vars) => {
			const key = JSON.stringify(args)
			const match = argMap.get(key)
			if (match && Date.now() - match.timestamp < 1_000) {
				return match.result
			}
			const result = bootDevServer({ variables: args })
			argMap.set(key, { result, timestamp: Date.now() })
			return result
		},
		10000,
		{ leading: true, trailing: false }
	)

	return throttled
}
